const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = parseInt(data[0], 10);
const p = data[1];

const pref = new Int32Array((n + 1) * 26);

for (let i = 0; i < n; i++) {
  const prev = i * 26;
  const cur = (i + 1) * 26;
  for (let c = 0; c < 26; c++) {
    pref[cur + c] = pref[prev + c];
  }
  pref[cur + (p.charCodeAt(i) - 97)]++;
}

function check(L) {
  const targetBase = L * 26;
  for (let s = L; s < n; s += L) {
    const startBase = s * 26;
    const endBase = (s + L) * 26;
    for (let c = 0; c < 26; c++) {
      if (pref[endBase + c] - pref[startBase + c] !== pref[targetBase + c]) {
        return false;
      }
    }
  }
  return true;
}

let ans = null;

for (let L = 1; L * 2 <= n; L++) {
  if (n % L === 0 && check(L)) {
    ans = p.slice(0, L);
    break;
  }
}

console.log(ans === null ? '*' : ans);
